#include <ArduinoOTA.h>

void enterFlashMode() {
  Serial.println("Starte Flash-Modus...");

  WiFi.mode(WIFI_STA);
  WiFi.begin(ssid, password);

  Serial.print("Verbinde mit WLAN");

  unsigned long start = millis();

  while (WiFi.status() != WL_CONNECTED) {
    delay(250);
    Serial.print(".");

    // Nach 15 Sekunden abbrechen
    if (millis() - start > 15000) {
      Serial.println("\nWLAN-Verbindung fehlgeschlagen!");
      return;
    }
  }

  Serial.println();
  Serial.println("WLAN verbunden.");
  Serial.print("IP-Adresse: ");
  Serial.println(WiFi.localIP());
  textWindowRunning(String(WiFi.localIP()).c_str());
  ArduinoOTA.setHostname("ESP32-Flash");

  ArduinoOTA.onStart([]() {
    Serial.println("Flash-Vorgang gestartet...");
  });

  ArduinoOTA.onEnd([]() {
    Serial.println("\nFlash-Vorgang abgeschlossen!");
  });

  ArduinoOTA.onProgress([](unsigned int progress, unsigned int total) {
    Serial.printf("Flash: %u%%\r", (progress * 100) / total);
  });

  ArduinoOTA.onError([](ota_error_t error) {
    Serial.printf("\nOTA-Fehler: %u\n", error);
  });

  ArduinoOTA.begin();

  Serial.println("================================");
  Serial.println("ESP32 ist jetzt im Flash-Modus!");
  Serial.println("================================");

  // Im Flash-Modus bleiben
  while (true) {
    ArduinoOTA.handle();
    delay(1);
  }
}


#include <Adafruit_NeoPixel.h>

#define MATRIX_PIN   27
#define MATRIX_LEDS  25
#define MATRIX_W      5
#define MATRIX_H      5

Adafruit_NeoPixel matrix(
  MATRIX_LEDS,
  MATRIX_PIN,
  NEO_GRB + NEO_KHZ800
);


// --------------------------------------------------
// Matrix initialisieren
// --------------------------------------------------

void initMatrix() {
  matrix.begin();
  matrix.setBrightness(40);
  matrix.clear();
  matrix.show();
}


// --------------------------------------------------
// LED-Index für deine Serpentinen-Verdrahtung
// --------------------------------------------------

int matrixIndex(int x, int y) {

  if (x < 0 || x >= MATRIX_W ||
      y < 0 || y >= MATRIX_H)
    return -1;

  // Jede zweite Reihe ist umgedreht
  if (y & 1)
    x = MATRIX_W - 1 - x;

  return y * MATRIX_W + x;
}


// --------------------------------------------------
// 5x5-Schrift
// --------------------------------------------------

const byte fontH[5] = {
  0b10001,
  0b10001,
  0b11111,
  0b10001,
  0b10001
};

const byte fontA[5] = {
  0b01110,
  0b10001,
  0b11111,
  0b10001,
  0b10001
};

const byte fontL[5] = {
  0b10000,
  0b10000,
  0b10000,
  0b10000,
  0b11111
};

const byte fontO[5] = {
  0b01110,
  0b10001,
  0b10001,
  0b10001,
  0b01110
};

const byte fontW[5] = {
  0b10001,
  0b10001,
  0b10101,
  0b10101,
  0b01010
};

const byte fontE[5] = {
  0b11111,
  0b10000,
  0b11110,
  0b10000,
  0b11111
};

const byte fontT[5] = {
  0b11111,
  0b00100,
  0b00100,
  0b00100,
  0b00100
};


// --------------------------------------------------
// Farbe: langsam durch den Farbkreis
// --------------------------------------------------

uint32_t matrixColor(byte hue) {

  if (hue < 85) {
    return matrix.Color(
      255 - hue * 3,
      hue * 3,
      0
    );
  }

  if (hue < 170) {
    hue -= 85;

    return matrix.Color(
      0,
      255 - hue * 3,
      hue * 3
    );
  }

  hue -= 170;

  return matrix.Color(
    hue * 3,
    0,
    255 - hue * 3
  );
}


// --------------------------------------------------
// Einen Buchstaben zeichnen
// --------------------------------------------------

void drawMatrixChar(
  const byte character[5],
  int offsetX,
  uint32_t color
) {

  for (int y = 0; y < 5; y++) {

    for (int x = 0; x < 5; x++) {

      if (character[y] & (1 << (4 - x))) {

        int px = offsetX + x;
        int index = matrixIndex(px, y);

        if (index >= 0)
          matrix.setPixelColor(index, color);
      }
    }
  }
}


// --------------------------------------------------
// "HALLO WELT"
// --------------------------------------------------

void writeHello() {

  static int scroll = MATRIX_W;
  static uint8_t hue = 0;
  static unsigned long lastFrame = 0;

  // 25 FPS
  const unsigned long frameTime = 1000 / 25;

  unsigned long now = millis();

  if (now - lastFrame < frameTime)
    return;

  lastFrame = now;

  // Farbe unabhängig vom Text verändern
  hue++;

  uint32_t color = matrixColor(hue);

  matrix.clear();

  /*
       HALLO WELT

       Jeder Buchstabe = 5 Pixel breit
       + 1 Pixel Abstand
  */

  const byte* text[] = {
    fontH,
    fontA,
    fontL,
    fontL,
    fontO,
    nullptr,
    fontW,
    fontE,
    fontL,
    fontT
  };

  const int textLength = 10;

  for (int i = 0; i < textLength; i++) {

    // Leerzeichen
    if (text[i] == nullptr)
      continue;

    int x = scroll + i * 6;

    drawMatrixChar(
      text[i],
      x,
      color
    );
  }

  matrix.show();

  // Laufschrift
  scroll--;

  // 10 Zeichen × 6 Pixel
  const int textWidth = textLength * 6;

  if (scroll < -textWidth)
    scroll = MATRIX_W;
}
